import java.io.BufferedReader;
import java.io.File;
import java.io.FileReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class e_e86 {

	static int MOD = 998244353;
	static long fact [];

	public static void main(String[] args) throws Exception {
		// TODO Auto-generated method stub

		FastScanner in = new FastScanner(System.in);
		OutputStream outputStream = System.out;
		PrintWriter out = new PrintWriter(outputStream);

		int N = in.nextInt();
		long pk = in.nextLong();
		if(pk > N-1) {
			out.println(0);
		}else {
			int k = (int) pk;
			fact = new long [N+1];

			fact[0] = 1;
			for(int i = 1; i <= N; i++) {
				fact[i] = (i*fact[i-1])%MOD;
			}

			long ans = 0;
			int dir = 1;
			int c = N-k;
			for(int i = c; i >= 0; i--) {
				long dif = (choose(c, i)*power(i, N))%MOD;
				dif = dir*dif;
				ans = (ans + dif + MOD)%MOD;

		//		out.println(dir*(((choose(c, i))*power(i, N) + MOD)%MOD + MOD)%MOD +" " + choose(c, i) + " " + power(i, N));
				dir = -dir;
			}

			ans = (ans*choose(N, c))%MOD;
			if(k > 0) {
				ans = (2*ans)%MOD;
			}

			out.println(ans);
		}

		out.close();


	}

	static long choose(int a, int b) {
		long res = (fact[a] * inv((fact[b] * fact[a-b])%MOD))%MOD;
		return res;
	}

	static long power (long x, int y) {
		long res = 1;
		while(y > 0) {
			if(y%2 == 1) res = (res*x)%MOD;
			x = (x*x)%MOD;
			y /= 2;
		}
		return (res%MOD);
	}

	static long inv (long a) {
		return power(a, MOD-2);
	}

	static class FastScanner {
		BufferedReader br;
		StringTokenizer st;

		public FastScanner(InputStream stream) {
			br = new BufferedReader(new InputStreamReader(stream));
			st = new StringTokenizer("");
		}

		public FastScanner(String fileName) throws Exception {
			br = new BufferedReader(new FileReader(new File(fileName)));
			st = new StringTokenizer("");
		}

		public String next() throws Exception {
			while (!st.hasMoreTokens()) {
				st = new StringTokenizer(br.readLine());
			}
			return st.nextToken();
		}

		public int nextInt() throws Exception {
			return Integer.parseInt(next());
		}

		public long nextLong() throws Exception {
			return Long.parseLong(next());
		}

		public Double nextDouble() throws Exception {
			return Double.parseDouble(next());
		}

		public String nextLine() throws Exception {
			if (st.hasMoreTokens()) {
				StringBuilder str = new StringBuilder();
				boolean first = true;
				while (st.hasMoreTokens()) {
					if (first) {
						first = false;
					} else {
						str.append(" ");
					}
					str.append(st.nextToken());
				}
				return str.toString();
			} else {
				return br.readLine();
			}
		}
	}


}

